package com.claudecode.core.engine;

/**
 * Structured explanation of a permission request generated by calling the Haiku model with the tool
 * name and input.
 */
public record PermissionExplanation(
    /** Risk level: "LOW" | "MEDIUM" | "HIGH". */
    String riskLevel,
    /** What the command does (1-2 sentences). */
    String explanation,
    /** Why the agent is running this command (starts with "I"). */
    String reasoning,
    /** Short description of what could go wrong (under 15 words). */
    String risk
) {}
